#include <OpenMS/METADATA/PeptideIdentification.h>
#include <OpenMS/FORMAT/IdentificationDataFile.h>
#include <OpenMS/METADATA/MetaInfo.h>
#include <fstream>
#include <iostream>
#include <map>
#include <malloc.h>
#include <sys/resource.h>
#include <unistd.h>
#include <cstdint>
using namespace OpenMS;
using ID = IdentificationData;
std::map<std::string, UInt64> totals;
void memory(const char* label)
{
  std::ifstream in("/proc/self/statm");
  unsigned long pages, resident;
  in >> pages >> resident;
  rusage r{}; getrusage(RUSAGE_SELF, &r);
  auto mi = mallinfo2();
  std::cout << "MEMORY " << label << " rss_kib=" << resident * sysconf(_SC_PAGESIZE) / 1024
            << " peak_kib=" << r.ru_maxrss << " glibc_allocated=" << mi.uordblks + mi.hblkhd
            << " glibc_free=" << mi.fordblks << '\n';
}
void string(const std::string& s)
{
  auto p = reinterpret_cast<std::uintptr_t>(s.data());
  auto begin = reinterpret_cast<std::uintptr_t>(&s);
  if (p < begin || p >= begin + sizeof(s)) totals["string_heap_capacity"] += s.capacity() + 1;
}
void meta(const MetaInfoInterface& m)
{
  if (!m.metaSize()) return;
  totals["metadata_object_and_used_entries"] += sizeof(MetaInfo) + m.metaSize() * sizeof(std::pair<UInt, DataValue>);
  for (auto it = m.metaBegin(); it != m.metaEnd(); ++it)
  {
    if (it->second.valueType() == DataValue::STRING_VALUE)
    {
      totals["metadata_string_objects"] += sizeof(std::string);
      auto s = it->second.toString();
      if (s.size() > 15) totals["metadata_string_minimum_heap"] += s.size() + 1;
    }
  }
}
int main(int argc, char** argv)
{
  if (argc != 3) return 2;
#define SIZE(T) std::cout << "SIZE " #T " " << sizeof(T) << '\n'
  SIZE(ID::Identification); SIZE(ID::Observation); SIZE(ID::Match); SIZE(ID::MatchData); SIZE(ID::ParentEvidence);
  SIZE(std::optional<AdductInfo>); SIZE(std::optional<std::string>); SIZE(MetaInfoInterface); SIZE(MetaInfo); SIZE(DataValue);
  SIZE(std::string); SIZE(std::vector<double>); SIZE(PeptideHit); SIZE(PeptideIdentification);
  memory("before");
  if (std::string(argv[1]) == "scan")
  {
    UInt64 queries = 0, matches = 0;
    auto stats = IdentificationDataFile::scan(argv[2], {},
      [&](const auto&, const auto& batch) { queries += batch.size(); },
      [&](const auto&, const auto& batch) { matches += batch.size(); });
    std::cout << "COUNTS queries=" << queries << " matches=" << matches << '\n';
    memory("scanned");
    return 0;
  }
  ID data;
  IdentificationDataFile::load(argv[2], data);
  memory("loaded");
  for (const auto& run : data.getRuns())
    for (const auto& block : run.getSourceBlocks())
    {
      totals["query_objects"] += block.identifications.size() * sizeof(ID::Identification);
      totals["query_spare_capacity"] += (block.identifications.capacity() - block.identifications.size()) * sizeof(ID::Identification);
      for (const auto& q : block.identifications)
      {
        string(q.data_id); meta(q);
        totals["match_objects"] += q.getMatches().size() * sizeof(ID::Match);
        totals["match_spare_capacity"] += (q.getMatches().capacity() - q.getMatches().size()) * sizeof(ID::Match);
        for (const auto& m : q.getMatches())
        {
          string(m.representation); string(m.name); meta(m);
          if (m.formula) string(*m.formula);
          totals["score_capacity"] += m.getScoreValues().capacity() * sizeof(double);
          totals["parent_evidence_capacity"] += m.parent_evidence.capacity() * sizeof(ID::ParentEvidence);
          for (const auto& e : m.parent_evidence)
          { string(e.parent.database); string(e.parent.accession); string(e.before); string(e.after); }
          totals["empty_adducts"] += !m.adduct;
          totals["empty_formulas"] += !m.formula;
          totals["empty_annotations"] += m.peak_annotations.empty();
        }
      }
    }
  for (const auto& [k,v] : totals) std::cout << "TOTAL " << k << " " << v << '\n';
  memory("enumerated");
  malloc_trim(0);
  memory("trimmed");
  { ID empty; data.swap(empty); }
  memory("destroyed");
  malloc_trim(0);
  memory("destroyed_trimmed");
}
